<?php
namespace App\Http\Controllers;
use App\Models\ActivityLog;
use App\Models\Currency;
use App\Models\DocumentSequence;
use App\Models\JournalEntry;
use App\Models\LedgerAccount;
use App\Models\TradeDocument;
use App\Models\TradeParty;
use App\Services\Accounting\JournalPostingService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
class TradeDocumentController extends Controller {
 public function index(Request $request){abort_unless($request->user()->can('administration.view'),403);$type=$request->validate(['type'=>['nullable',Rule::in(['receivable','payable'])]])['type']??'receivable';return view('finance.documents.index',['type'=>$type,'documents'=>TradeDocument::with(['party','currency'])->withSum('allocations','amount')->where('type',$type)->latest()->paginate(25)->withQueryString(),'parties'=>TradeParty::with('currencies')->where('type',$type==='receivable'?'customer':'supplier')->where('is_active',true)->orderBy('name')->get(),'currencies'=>Currency::where('is_active',true)->orderBy('code')->get(),'ledgers'=>LedgerAccount::where('is_group',false)->where('is_active',true)->orderBy('code')->get(),'settlementTransactions'=>\App\Models\MoneyTransaction::withSum('allocations','amount')->where('type',$type==='receivable'?'receipt':'payment')->latest('id')->limit(300)->get()->filter(fn($t)=>(float)$t->amount-(float)($t->allocations_sum_amount??0)>0)->values(),'settlementLedgerMap'=>DB::table('entity_ledger_accounts')->where('entity_type',$type==='receivable'?'customer':'supplier')->where('purpose',$type)->get()->keyBy(fn($row)=>$row->entity_id.':'.$row->currency_id)]);}
 public function store(Request $request,JournalPostingService $posting){abort_unless($request->user()->can('administration.update'),403);$data=$request->validate(['type'=>['required',Rule::in(['receivable','payable'])],'trade_party_id'=>['required','exists:trade_parties,id'],'currency_id'=>['required','exists:currencies,id'],'document_date'=>['required','date'],'due_date'=>['required','date','after_or_equal:document_date'],'amount'=>['required','numeric','gt:0','decimal:0,4','max:999999999999.9999'],'counterpart_ledger_account_id'=>['required','exists:ledger_accounts,id'],'reference'=>['nullable','string','max:100'],'description'=>['required','string','max:2000']]);DB::transaction(function()use($data,$request,$posting){$party=TradeParty::whereKey($data['trade_party_id'])->lockForUpdate()->firstOrFail();$expected=$data['type']==='receivable'?'customer':'supplier';if(!$party->is_active||$party->type!==$expected||!$party->currencies()->whereKey($data['currency_id'])->exists())throw ValidationException::withMessages(['trade_party_id'=>'Choose an active matching customer or supplier with this currency enabled.']);$purpose=$data['type']==='receivable'?'receivable':'payable';$partyLedger=DB::table('entity_ledger_accounts')->where(['entity_type'=>$expected,'entity_id'=>$party->id,'currency_id'=>$data['currency_id'],'purpose'=>$purpose])->value('ledger_account_id');$counterpart=LedgerAccount::findOrFail($data['counterpart_ledger_account_id']);if(!$partyLedger||!$counterpart->is_active||$counterpart->is_group||$counterpart->id===$partyLedger)throw ValidationException::withMessages(['counterpart_ledger_account_id'=>'Select a valid active posting ledger different from the trade account.']);$sequence=$data['type']==='receivable'?'manual_receivable':'manual_payable';DocumentSequence::firstOrCreate(['document_type'=>$sequence],['prefix'=>$sequence==='manual_receivable'?'MAR-':'MAP-','next_number'=>1,'padding'=>6,'is_active'=>true]);$number=DocumentSequence::issue($sequence);$journal=JournalEntry::create(['number'=>$number,'entry_date'=>$data['document_date'],'reference'=>$data['reference']??null,'description'=>$data['description'],'currency_id'=>$data['currency_id'],'created_by'=>$request->user()->id,'status'=>'draft']);$debit=$data['type']==='receivable'?$partyLedger:$counterpart->id;$credit=$data['type']==='receivable'?$counterpart->id:$partyLedger;$journal->lines()->create(['ledger_account_id'=>$debit,'debit'=>$data['amount'],'credit'=>0]);$journal->lines()->create(['ledger_account_id'=>$credit,'debit'=>0,'credit'=>$data['amount']]);$posting->post($journal,$request->user()->id);$doc=TradeDocument::create(['type'=>$data['type'],'number'=>$number,'trade_party_id'=>$party->id,'currency_id'=>$data['currency_id'],'document_date'=>$data['document_date'],'due_date'=>$data['due_date'],'amount'=>$data['amount'],'reference'=>$data['reference']??null,'description'=>$data['description'],'journal_entry_id'=>$journal->id,'created_by'=>$request->user()->id]);ActivityLog::record('trade_document.posted','trade_document',$doc->id,$number.' posted');});return redirect()->route('finance.documents.index',['type'=>$data['type']])->with('status','Trade document posted to the General Ledger.');}
}
